head.b:skin:
:root{--void:#080c14;--bg:#080c14;--panel:#0f1723;--panel-2:#0b121c;--line:#1d2a3b;--signal:#a8ff60;--signal-dim:#6fbf3e;--ceibal:#ff8a3d;--orbit:#5ec8ff;--ink:#e9eff6;--mute:#7c8ba0;--mute-2:#4c5a6e;--font-display:"Space Mono",monospace;--font-body:"Inter",sans-serif;--font-data:"JetBrains Mono",monospace;--container:1152px;--radius:12px}
[data-theme="light"]{--bg:#f6f7fa;--panel:#ffffff;--panel-2:#eceff3;--line:#d7dde6;--signal:#3f9d24;--signal-dim:#357f1e;--ceibal:#d96a1f;--orbit:#1582c4;--ink:#161d2a;--mute:#57657b;--mute-2:#8a96a8}
[data-theme="light"] .status-bar{background:rgba(255,255,255,.85)}
[data-theme="light"] .dropdown-menu{box-shadow:0 20px 40px rgba(20,26,36,.14)}
[data-theme="light"] ::selection{background:var(--signal);color:#fff}
.theme-toggle{display:inline-flex;align-items:center;justify-content:center;width:40px;height:40px;margin-left:4px;color:var(--mute);background:var(--panel);border:1px solid var(--line);border-radius:999px;cursor:pointer;transition:border-color .2s,color .2s,background-color .2s}.theme-toggle:hover{color:var(--orbit);border-color:var(--orbit)}
*,*:before,*:after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:20px}
body{margin:0;min-width:320px;overflow-x:hidden;font-family:var(--font-body);color:var(--ink);background-color:var(--bg);line-height:1.5;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
img,svg{max-width:100%;height:auto}button,input{font:inherit}button,a{-webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button{cursor:pointer}
::selection{background:var(--signal);color:#08110a}:focus-visible{outline:2px solid var(--orbit);outline-offset:3px}
.container{width:min(calc(100% - 40px),var(--container));margin-inline:auto}.font-display{font-family:var(--font-display)}.font-data{font-family:var(--font-data)}
.text-signal{color:var(--signal)}.text-orbit{color:var(--orbit)}.text-ceibal{color:var(--ceibal)}.text-ink{color:var(--ink)}.text-mute{color:var(--mute)}.text-mute-2{color:var(--mute-2)}
.lucide{width:1em;height:1em;vertical-align:-.125em;stroke-width:2;flex-shrink:0}
.bg-scan{background-image:radial-gradient(ellipse 80% 50% at 50% -10%,rgba(168,255,96,.10),transparent 60%),radial-gradient(ellipse 60% 40% at 90% 10%,rgba(94,200,255,.08),transparent 60%)}
.grid-lines{background-image:linear-gradient(rgba(233,239,246,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(233,239,246,.035) 1px,transparent 1px);background-size:42px 42px}
.status-bar{border-bottom:1px solid var(--line);background:rgba(11,18,28,.8);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
.status-inner{min-height:36px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding-block:8px;font-family:var(--font-data);font-size:12px;color:var(--mute)}
.status-signal{display:inline-block;width:6px;height:6px;margin-right:8px;border-radius:50%;background:var(--signal);box-shadow:0 0 8px var(--signal);vertical-align:middle}.status-inner>div{display:flex;align-items:center}
.status-nav{display:flex;align-items:center;gap:20px}.status-nav a{transition:color .2s ease}.status-nav a:hover{color:var(--signal)}
/* .hero ya NO usa overflow:hidden: recortaba el dropdown y lo dejaba tapado por la sección de newsletter */
.hero{position:relative;border-bottom:1px solid var(--line)}.hero-inner{position:relative;padding-top:64px;padding-bottom:80px}
.hero-content{display:flex;flex-direction:column;align-items:center;text-align:center}
.orbital-logo{display:block;position:relative;width:112px;height:112px;margin-bottom:24px;flex-shrink:0;transition:transform .2s ease}.orbital-logo:hover{transform:scale(1.04)}.orbit{position:absolute;inset:0;border:1px dashed rgba(94,200,255,.4);border-radius:50%}.orbit.second{inset:12px;border-color:rgba(255,138,61,.3)}
.orbit-center{position:absolute;inset:0;display:grid;place-items:center}.orbit-center:after{content:"";width:36px;height:36px;border-radius:50%;background:var(--signal);box-shadow:0 0 30px rgba(168,255,96,.55)}
.orbit-dot{position:absolute;top:-2px;left:50%;width:8px;height:8px;border-radius:50%;background:var(--orbit);box-shadow:0 0 10px var(--orbit);transform:translateX(-50%)}
.hero-kicker{margin:0 0 12px;font-family:var(--font-data);font-size:12px;letter-spacing:.35em;text-transform:uppercase;color:var(--mute)}
.hero h1{margin:0;font-family:var(--font-display);font-size:clamp(2.25rem,7vw,3.75rem);line-height:1.1;letter-spacing:-.04em}.hero-description{width:min(100%,640px);margin:20px 0 0;font-size:clamp(.95rem,2vw,1.125rem);line-height:1.7;color:var(--mute)}
.hero-actions{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin-top:32px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:10px 20px;border-radius:6px;font-family:var(--font-display);font-size:14px;font-weight:700;transition:background-color .2s,border-color .2s,color .2s,transform .2s}.btn:hover{transform:translateY(-1px)}
.btn-primary{color:var(--void);background:var(--signal);border:1px solid var(--signal)}.btn-primary:hover{background:var(--signal-dim);border-color:var(--signal-dim)}.btn-secondary{color:var(--ink);background:transparent;border:1px solid var(--line)}.btn-secondary:hover{color:var(--orbit);border-color:var(--orbit)}
.nav-toggle{display:none}.nav-toggle-icon{display:inline-block;position:relative;width:16px;height:2px;background:currentColor;border-radius:2px}.nav-toggle-icon:before,.nav-toggle-icon:after{content:"";position:absolute;left:0;width:16px;height:2px;background:currentColor;border-radius:2px}.nav-toggle-icon:before{top:-5px}.nav-toggle-icon:after{top:5px}.main-nav{position:relative;z-index:5;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:8px;margin-top:56px;font-family:var(--font-data);font-size:14px}
.nav-link,.dropdown-toggle{display:inline-flex;align-items:center;gap:5px;min-height:40px;padding:8px 16px;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:999px;transition:border-color .2s,color .2s,background-color .2s}.nav-link:hover,.dropdown-toggle:hover{color:var(--signal);border-color:var(--signal)}.nav-badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:999px;background:var(--signal);color:var(--void);font-family:var(--font-data);font-size:11px;font-weight:700;line-height:1}.nav-badge[hidden]{display:none}
.dropdown{position:relative}.dropdown summary{list-style:none}.dropdown summary::-webkit-details-marker{display:none}.dropdown-menu{position:absolute;z-index:60;top:calc(100% + 8px);left:0;width:180px;padding:5px;background:var(--panel);border:1px solid var(--line);border-radius:10px;box-shadow:0 20px 40px rgba(0,0,0,.35)}
.dropdown-menu a{display:block;padding:10px 12px;border-radius:6px;color:var(--ink)}.dropdown-menu a:hover{color:var(--signal);background:var(--panel-2)}
.search-box{position:relative;width:210px;margin-left:4px}.search-box input{width:100%;height:40px;padding:8px 38px 8px 16px;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:999px;font-size:14px}.search-box input::placeholder{color:var(--mute-2)}.search-box input:focus{outline:none;border-color:var(--orbit);box-shadow:0 0 0 1px var(--orbit)}.search-icon{position:absolute;top:50%;right:14px;color:var(--mute-2);font-size:14px;transform:translateY(-50%);pointer-events:none}
.newsletter{position:relative;z-index:1;border-bottom:1px solid var(--line);background:var(--panel-2)}.newsletter-inner{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-block:16px}.newsletter-text{display:flex;align-items:center;gap:8px;margin:0;font-family:var(--font-data);font-size:14px;color:var(--mute)}.blink{color:var(--signal)}
.newsletter-form{display:flex;width:100%;max-width:360px;gap:8px}    .newsletter-form input{flex:1;min-width:0;padding:10px 16px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:6px}.newsletter-form input:focus{outline:none;border-color:var(--signal);box-shadow:0 0 0 1px var(--signal)}.newsletter-form button{flex-shrink:0;padding:10px 16px;color:var(--void);background:var(--ceibal);border:1px solid var(--ceibal);border-radius:6px;font-family:var(--font-display);font-size:12px;font-weight:700}
.tag-cloud{padding-block:32px;border-bottom:1px solid var(--line)}.tag-cloud-inner{display:flex;flex-wrap:wrap;justify-content:center;align-items:center;gap:8px 14px}    .tag-cloud a:hover{color:var(--signal);text-decoration:underline}.tag-large{font-family:var(--font-display);font-size:18px}.tag-medium{font-size:14px;color:var(--ink)}.tag-small{font-size:12px;color:var(--mute)}
.main-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:48px;padding-top:56px;padding-bottom:56px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:32px}.heading-title{display:inline-flex;align-items:center;gap:10px}.section-heading h2{margin:0;font-family:var(--font-display);font-size:20px;line-height:1.3}.heading-meta{display:inline-flex;align-items:center;gap:6px;color:var(--mute);font-family:var(--font-data);font-size:12px}.heading-meta a{color:var(--mute)}.heading-meta a:hover{color:var(--signal)}
.posts{display:grid;gap:20px}.blog-posts{display:grid;gap:20px}.post{display:grid;grid-template-columns:minmax(0,1fr);gap:20px;align-items:start;padding:24px;background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);transition:border-color .2s,transform .2s}.post:hover{border-color:rgba(168,255,96,.5);transform:translateY(-2px)}.post:has(.post-cover){grid-template-columns:minmax(0,200px) minmax(0,1fr)}.post-cover{margin:0}.post-cover img{display:block;width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:10px;border:1px solid var(--line)}.post-content{min-width:0}
.post-empty{text-align:center;color:var(--mute);padding:40px 24px;border:1px dashed var(--line);border-radius:var(--radius);font-size:14px}
.post-meta{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;margin-bottom:12px;color:var(--mute);font-family:var(--font-data);font-size:12px}.post-author{color:var(--mute)}.post-tag{padding:2px 8px;background:var(--bg);border:1px solid var(--line);border-radius:4px}.post-tag:hover{color:var(--signal);border-color:var(--signal)}.post-tag.tag-orbit:hover{color:var(--orbit);border-color:var(--orbit)}.post-tag.tag-ceibal:hover{color:var(--ceibal);border-color:var(--ceibal)}
.post h3,.post-title{margin:0 0 8px;font-family:var(--font-display);font-size:18px;line-height:1.45}.post h3 a:hover{color:var(--signal)}.post-title{font-size:28px;line-height:1.25}.post-description{margin:0 0 16px;color:var(--mute);font-size:14px;line-height:1.7}.post-body{margin:0 0 20px;font-size:15px;line-height:1.8;color:var(--ink)}.post-body a{color:var(--signal);text-decoration:underline;text-underline-offset:3px}.post-body img{max-width:100%;height:auto;border-radius:8px}.post-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;font-family:var(--font-data);font-size:12px}.read-more{color:var(--signal)}.read-more:hover{text-decoration:underline}.comment-count-link{color:var(--mute)}.comment-count-link:hover{color:var(--signal)}
.comment-count-wrap{display:inline-flex;align-items:center;gap:6px}.share-row{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.share-row-label{display:inline-flex;align-items:center;gap:6px;color:var(--mute);font-family:var(--font-data);font-size:11px;letter-spacing:.08em;text-transform:uppercase}.share-btn{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;padding:0;color:var(--mute);background:var(--panel);border:1px solid var(--line);border-radius:6px;cursor:pointer;transition:color .2s,border-color .2s,transform .2s}.share-btn svg{width:17px;height:17px}.share-btn .brand{fill:currentColor}.share-btn:hover{color:var(--signal);border-color:var(--signal);transform:translateY(-1px)}.hero-content .share-row{margin-top:32px}
section.comments{margin-top:32px;padding:24px;background:var(--panel);border:1px solid var(--line);border-radius:var(--radius)}.comments .title{font-family:var(--font-display);font-size:18px;margin:0 0 16px}.comments .comments-content{margin:0;padding:0}.comments .comment{list-style:none;margin:0 0 14px;padding:14px 16px;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius)}.comments .comment-header{display:flex;align-items:baseline;gap:8px;font-family:var(--font-data);font-size:12px;color:var(--mute)}.comments .comment-header .user{color:var(--signal)}.comments .comment-body{color:var(--ink);font-size:14px;line-height:1.7}.comments .comment-actions a,.comments .comment-replybox-thread a{color:var(--orbit);font-size:12px;font-family:var(--font-data)}.comments #comment-editor,.comments .comment-replybox-single iframe,.comments .comment-replybox-thread iframe{border-radius:var(--radius)}[data-theme="dark"] .comments #comment-editor,[data-theme="dark"] .comments .comment-replybox-single iframe,[data-theme="dark"] .comments .comment-replybox-thread iframe{filter:invert(.9) hue-rotate(180deg)}.comments .comment-form{max-width:520px;margin-top:24px}.comments .comment-form iframe{width:100%;border:0}.comments .comment-thread ol,.comments .comment-replies ol{margin:0;padding:0;list-style:none}.comments .comment-content{color:var(--ink);font-size:14px;line-height:1.7;margin:8px 0}.comments .comment-header .datetime{color:var(--mute)}.comments .avatar-image-container{float:right;margin:0 0 6px 10px}.comments .avatar-image-container img{display:block;width:32px;height:32px;border-radius:50%;background:var(--panel)}.comments .comment-replies{margin:10px 0 0 18px;padding-left:18px;border-left:1px solid var(--line)}.comments .comment-replybox-single,.comments .comment-replybox-thread{margin-top:10px}.comments .comment-replybox-single iframe,.comments .comment-replybox-thread iframe{width:100%;border:0}.xogalaxy-comments .cmts-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 16px}.xogalaxy-comments .cmts-title{font-family:var(--font-display);font-size:18px;margin:0}.cmts-toggle{padding:8px 14px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:999px;font-family:var(--font-data);font-size:12px;cursor:pointer}.cmts-toggle:hover{color:var(--signal);border-color:var(--signal)}.cmts-list{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:14px}.cmt{padding:14px 16px;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius)}.cmt-header{display:flex;align-items:center;gap:8px;margin:0 0 6px}.cmt-avatar{width:32px;height:32px;border-radius:50%;object-fit:cover;background:var(--panel)}.cmt-name{color:var(--signal);font-family:var(--font-display);font-size:13px}.cmt-name.cmt-verified::after{content:"\2713";margin-left:4px;color:var(--orbit)}.cmt-when{margin-left:auto;color:var(--mute);font-family:var(--font-data);font-size:11px}.cmt-body{color:var(--ink);font-size:14px;line-height:1.7;word-break:break-word}.cmt-none{color:var(--mute);font-family:var(--font-data);font-size:13px}.cmts-status{color:var(--mute);font-family:var(--font-data);font-size:12px;margin:8px 0}.cmts-status.error{color:var(--ceibal)}.cmts-status.pending{color:var(--orbit)}.cmts-form-wrap{margin-top:20px}.cmts-form{display:flex;flex-direction:column;gap:10px}.cmts-auth{display:flex;align-items:center;gap:10px;flex-wrap:wrap;min-height:40px}.cmts-who{color:var(--ink);font-size:13px}.cmts-anon{display:flex;flex-direction:column;gap:4px}.cmts-name,.cmts-body{padding:9px 12px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:6px;font-size:14px}.cmts-name{max-width:220px}.cmts-body{min-height:90px;resize:vertical}.cmts-name:focus,.cmts-body:focus{outline:none;border-color:var(--orbit);box-shadow:0 0 0 1px var(--orbit)}.cmts-hint{margin:0;color:var(--mute);font-family:var(--font-data);font-size:11px}.cmts-submit{align-self:flex-start;padding:9px 18px;color:var(--void);background:var(--signal);border:1px solid var(--signal);border-radius:6px;font-family:var(--font-display);font-size:12px;font-weight:700}.cmts-submit:hover{background:var(--signal-dim);border-color:var(--signal-dim)}.cmts-submit:disabled{opacity:.5;cursor:not-allowed}.cmts-logout{padding:6px 12px;color:var(--mute);background:transparent;border:1px solid var(--line);border-radius:999px;font-family:var(--font-data);font-size:11px;cursor:pointer}.cmts-logout:hover{color:var(--signal);border-color:var(--signal)}.cmts-mod{margin-top:24px;padding-top:16px;border-top:1px dashed var(--line)}.cmts-mod-toggle{padding:7px 12px;color:var(--orbit);background:transparent;border:1px solid var(--orbit);border-radius:999px;font-family:var(--font-data);font-size:11px;cursor:pointer}.cmts-mod-list{margin:12px 0 0;padding:0;list-style:none;display:flex;flex-direction:column;gap:10px}.cmt-actions{display:flex;gap:8px;margin-top:8px}.cmt-approve,.cmt-reject{padding:5px 10px;border-radius:6px;font-family:var(--font-data);font-size:11px;cursor:pointer;border:1px solid}.cmt-approve{color:var(--signal);border-color:var(--signal);background:transparent}.cmt-approve:hover{background:var(--signal);color:var(--void)}.cmt-reject{color:var(--ceibal);border-color:var(--ceibal);background:transparent}.cmt-reject:hover{background:var(--ceibal);color:var(--void)}.chat-msg{display:flex;align-items:flex-start;gap:8px}.chat-msg-avatar{width:28px;height:28px;border-radius:50%;object-fit:cover;flex-shrink:0;background:var(--panel)}.chat-msg-verified::after{content:"\2713";margin-left:4px;color:var(--orbit)}
.load-more{display:flex;justify-content:center;margin-top:40px}.load-more a{display:inline-flex;align-items:center;gap:8px;padding:12px 24px;color:var(--ink);background:transparent;border:1px solid var(--line);border-radius:6px;font-family:var(--font-display);font-size:14px}.load-more a:hover{color:var(--signal);border-color:var(--signal)}
.sidebar{display:grid;align-content:start;gap:32px}.sidebar-card{padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:var(--radius)}.sidebar-title{display:flex;align-items:center;gap:8px;margin:0 0 16px;color:var(--mute);font-family:var(--font-display);font-size:12px;letter-spacing:.2em;text-transform:uppercase}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;text-align:center}.stat-value{margin:0;font-family:var(--font-display);font-size:20px;font-weight:700;min-height:1.4em}.stat-label{margin:2px 0 0;color:var(--mute);font-size:11px}.follow-btn{display:inline-flex;align-items:center;gap:6px;margin-top:10px;padding:6px 14px;border-radius:999px;color:var(--ceibal);background:transparent;border:1px solid var(--ceibal);font-family:var(--font-display);font-size:12px;font-weight:700;transition:background-color .2s,color .2s}.follow-btn:hover{background:var(--ceibal);color:var(--void)}.sidebar-description{margin:16px 0 0;color:var(--mute);font-size:12px;line-height:1.7}
.sidebar-tags{display:flex;flex-wrap:wrap;gap:6px}.pill{padding:4px 10px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:999px;font-size:12px}.pill:hover{color:var(--signal);border-color:var(--signal)}
.game-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 16px}.game-grid a{color:var(--ink);font-size:14px}.game-grid a:hover{color:var(--signal)}.sidebar-divider{margin:16px 0;border:0;border-top:1px dashed var(--line)}
.xo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.xo-grid a{padding:10px 5px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:6px;font-family:var(--font-data);font-size:11px;text-align:center}.xo-grid a:hover{color:var(--signal);border-color:var(--signal)}
.featured-list{display:grid;gap:10px;margin:0;padding:0;list-style:none}.featured-list li{display:flex;gap:12px;font-size:14px}.featured-number{width:20px;flex-shrink:0;color:var(--signal);font-family:var(--font-data)}.featured-list a{color:var(--ink)}.featured-list a:hover{color:var(--signal)}.featured-empty{color:var(--mute-2);font-size:13px;line-height:1.6}
.widget-content ul{margin:0;padding:0;list-style:none}.widget-content li{margin:0 0 7px}.widget-content a:hover{color:var(--signal)}.widget.Followers{display:none!important}
.faq{border-top:1px solid var(--line);background:var(--panel-2)}.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding-block:48px;text-align:center}.faq-number{display:flex;align-items:center;justify-content:center;gap:8px;margin:0 0 4px;font-family:var(--font-display);font-size:14px}.faq-item h3{margin:0 0 4px;font-family:var(--font-display);font-size:16px}.faq-item p{margin:0;color:var(--mute);font-size:14px;line-height:1.6}@keyframes chatpulse{0%,100%{opacity:1}50%{opacity:.35}}.chat{border-top:1px solid var(--line);background:var(--panel-2);padding-block:56px}#chat-app{height:480px;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;background:var(--bg)}.xogalaxy-chat{display:flex;flex-direction:column;height:100%}.xogalaxy-chat .chat-status{display:flex;align-items:center;gap:8px;margin:0;padding:10px 16px;border-bottom:1px solid var(--line);color:var(--mute);font-family:var(--font-data);font-size:12px}.xogalaxy-chat.chat-online .chat-status{color:var(--signal)}.xogalaxy-chat.chat-offline .chat-status{color:var(--ceibal)}.xogalaxy-chat .chat-status::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--mute-2);flex-shrink:0}.xogalaxy-chat.chat-online .chat-status::before{background:var(--signal);box-shadow:0 0 8px var(--signal);animation:chatpulse 1.4s ease-in-out infinite}.xogalaxy-chat.chat-offline .chat-status::before{background:var(--ceibal)}.chat-msgs{flex:1;margin:0;padding:12px 16px;overflow-y:auto;list-style:none;display:flex;flex-direction:column;gap:8px}.chat-msg{font-size:14px;line-height:1.5;word-break:break-word}.chat-msg-meta{color:var(--orbit);font-family:var(--font-data);font-size:11px;margin-right:8px;font-weight:700}.chat-msg-body{color:var(--ink)}.chat-form{display:flex;gap:8px;padding:10px;border-top:1px solid var(--line);background:var(--panel)}.chat-form input{min-width:0;padding:9px 12px;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:6px;font-size:14px}.chat-form input:focus{outline:none;border-color:var(--orbit);box-shadow:0 0 0 1px var(--orbit)}.chat-form .chat-nick{width:110px;flex-shrink:0}.chat-form .chat-input{flex:1}.chat-send{flex-shrink:0;padding:9px 16px;color:var(--void);background:var(--signal);border:1px solid var(--signal);border-radius:6px;font-family:var(--font-display);font-size:12px;font-weight:700}.chat-send:hover{background:var(--signal-dim);border-color:var(--signal-dim)}.chat-note{display:flex;align-items:center;justify-content:center;gap:8px;margin:12px 0 0;color:var(--mute);font-family:var(--font-data);font-size:12px;text-align:center}
footer{border-top:1px solid var(--line)}.footer-inner{display:flex;flex-direction:column;align-items:center;gap:20px;padding-block:40px;text-align:center}.footer-logo{display:flex;align-items:center;gap:8px;font-family:var(--font-display);font-size:14px}.footer-dot{width:8px;height:8px;border-radius:50%;background:var(--signal)}.footer-nav{display:flex;flex-wrap:wrap;justify-content:center;gap:8px 24px;color:var(--mute);font-family:var(--font-data);font-size:12px}.footer-nav a{display:inline-flex;align-items:center;gap:6px}.footer-nav a:hover{color:var(--signal)}.copyright{margin:0;color:var(--mute-2);font-size:11px}.footer-credit{margin:0;color:var(--mute-2);font-size:11px}.footer-credit a{color:var(--signal)}.footer-credit a:hover{text-decoration:underline}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@keyframes spin{to{transform:rotate(360deg)}}@keyframes spin-reverse{to{transform:rotate(-360deg)}}@keyframes blink{50%{opacity:0}}@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@media (prefers-reduced-motion:no-preference){.orbit{animation:spin 22s linear infinite;transform-origin:50% 50%}.orbit.second{animation:spin-reverse 30s linear infinite}.blink{animation:blink 1.4s steps(1) infinite}.post{animation:rise .6s cubic-bezier(.16,1,.3,1) both}.post:nth-child(2){animation-delay:.05s}.post:nth-child(3){animation-delay:.1s}.post:nth-child(4){animation-delay:.15s}.post:nth-child(5){animation-delay:.2s}.post:nth-child(6){animation-delay:.25s}}
@media (max-width:900px){.main-layout{grid-template-columns:1fr;gap:40px}.sidebar{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}.sidebar-card:first-child{grid-column:1/-1}.newsletter-inner{align-items:stretch;flex-direction:column}.newsletter-form{max-width:none}.post,.post:has(.post-cover){grid-template-columns:1fr}.post-title{font-size:24px}.nav-toggle{display:flex;align-items:center;justify-content:center;gap:8px;margin:28px auto 0;min-height:44px;padding:10px 16px;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:999px;font-family:var(--font-display);font-size:13px;font-weight:700;cursor:pointer}.nav-toggle:hover{color:var(--signal);border-color:var(--signal)}.main-nav{position:fixed;z-index:80;top:0;right:0;bottom:0;width:min(320px,85vw);margin:0;padding:24px;align-items:stretch;flex-direction:column;justify-content:flex-start;gap:4px;background:var(--panel);border-left:1px solid var(--line);box-shadow:-20px 0 40px rgba(0,0,0,.35);transform:translateX(100%);transition:transform .3s cubic-bezier(.16,1,.3,1);overflow-y:auto}.main-nav .nav-link,.main-nav .dropdown-toggle{justify-content:flex-start}.main-nav .dropdown-menu{position:static;width:100%;margin-top:6px;box-shadow:none}.main-nav .search-box{width:100%;margin:8px 0 0}body.nav-open{overflow:hidden}body.nav-open .main-nav{transform:translateX(0)}.nav-backdrop{position:fixed;z-index:70;inset:0;background:rgba(0,0,0,.55);opacity:0;pointer-events:none;transition:opacity .3s}body.nav-open .nav-backdrop{opacity:1;pointer-events:auto}}
@media (max-width:640px){.container{width:min(calc(100% - 28px),var(--container))}.status-inner{justify-content:center;text-align:center}.status-nav{display:none}.hero-inner{padding-top:48px;padding-bottom:56px}.orbital-logo{width:96px;height:96px}.orbit.second{inset:10px}.orbit-center:after{width:30px;height:30px}.hero-kicker{font-size:10px;letter-spacing:.22em}.hero-description{font-size:14px;line-height:1.7}.hero-actions{width:100%;flex-direction:column}.hero-actions .btn{width:100%}.newsletter-text{align-items:flex-start;text-align:center}.newsletter-form{flex-direction:column}.newsletter-form button{width:100%}.tag-cloud-inner{gap:7px 12px}.main-layout{padding-top:40px;padding-bottom:40px}.section-heading{flex-wrap:wrap}.heading-meta{width:100%}#feed .section-heading{flex-wrap:nowrap}#feed .heading-meta{width:auto}.share-row{justify-content:center}.share-row-label{width:100%;justify-content:center}.post{padding:18px}.post-footer{align-items:flex-start;flex-direction:column;gap:8px}.sidebar{grid-template-columns:1fr}.sidebar-card:first-child{grid-column:auto}.faq-grid{grid-template-columns:1fr;gap:32px;padding-block:40px}.chat{padding-block:40px}.chat-box{height:400px}.stats{grid-template-columns:repeat(2,1fr)}.footer-nav{gap:10px 18px}}
@media (max-width:380px){.container{width:min(calc(100% - 20px),var(--container))}.hero h1{font-size:2rem}.post-meta{align-items:flex-start;flex-direction:column}.stats{gap:6px}.xo-grid{grid-template-columns:1fr}}

body.script:
  //
/* XO Galaxy app.js — generado por web/build.mjs. No editar a mano. */
/**
 * XO Galaxy — core.
 * Utilidades + registro de hooks del SPA. Script clásico (sin imports/exports):
 * se concatena en web/dist/app.js junto a api/router/chunks y se inyecta en el template.
 */
(function (global) {
  "use strict";

  var X = (global.XOGalaxy = global.XOGalaxy || {});

  // ---- hooks (suscritores de ciclo de vida del SPA) ----
  var hooks = {};
  function addHook(name, fn) {
    (hooks[name] = hooks[name] || []).push(fn);
  }
  function runHooks(name, ctx) {
    (hooks[name] || []).forEach(function (fn) {
      try {
        fn(ctx);
      } catch (err) {
        if (global.console && console.error) console.error("[xogalaxy] hook", name, err);
      }
    });
  }

  // ---- DOM helpers ----
  function qs(sel, ctx) {
    return (ctx || document).querySelector(sel);
  }
  function qsa(sel, ctx) {
    return Array.prototype.slice.call((ctx || document).querySelectorAll(sel));
  }
  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text != null) node.textContent = text;
    return node;
  }
  function escHtml(str) {
    return String(str == null ? "" : str).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function fmt(n) {
    if (n >= 1000) return Math.round((n / 1000) * 10) / 10 + "k";
    return String(n);
  }
  function reduceMotion() {
    return global.matchMedia && global.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  // ---- fetch helpers ----
  function getJSON(url, opts) {
    return fetch(url, Object.assign({ headers: { accept: "application/json" } }, opts)).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    });
  }
  function postJSON(url, data) {
    return fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json", accept: "application/json" },
      body: JSON.stringify(data),
    }).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    });
  }
  function getText(url) {
    return fetch(url).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.text();
    });
  }

  // ---- UI helpers (reutilizados por chunks y tras cada navegación SPA) ----
  function animateStat(el2, target) {
    if (!el2 || isNaN(target)) return;
    if (reduceMotion()) {
      el2.textContent = fmt(target);
      return;
    }
    var duration = 1200,
      startTime = null;
    function step(ts) {
      if (!startTime) startTime = ts;
      var progress = Math.min((ts - startTime) / duration, 1);
      var eased = 1 - Math.pow(1 - progress, 3);
      el2.textContent = fmt(Math.floor(eased * target));
      if (progress < 1) requestAnimationFrame(step);
      else el2.textContent = fmt(target);
    }
    requestAnimationFrame(step);
  }

  function initIcons() {
    if (global.lucide && lucide.createIcons) {
      try {
        lucide.createIcons();
      } catch (err) {}
    }
  }

  function decorateTitle() {
    var titleEl = qs("#site-title");
    if (!titleEl || titleEl.getAttribute("data-decorated")) return;
    var raw = titleEl.textContent.replace(/\s+/g, " ").trim();
    var parts = raw.split(" ");
    if (parts.length > 1) {
      var first = parts.shift();
      titleEl.innerHTML =
        '<span class="text-signal">' + escHtml(first) + '</span><span class="text-ink"> ' + escHtml(parts.join(" ")) + "</span>";
    } else if (raw) {
      titleEl.innerHTML = '<span class="text-signal">' + escHtml(raw) + "</span>";
    }
    titleEl.setAttribute("data-decorated", "1");
  }

  function initFeedButton() {
    var btn = qs('.hero-actions a[href*="#feed"]');
    if (!btn) return;
    var isHome = (location.pathname || "/").replace(/\/+$/, "") === "";
    btn.setAttribute("href", isHome ? "#feed" : location.origin + "/#feed");
  }

  function setupNav() {
    var navToggle = qs(".nav-toggle");
    var navBackdrop = document.getElementById("nav-backdrop");
    if (!navToggle || !navBackdrop) return;
    function setNav(open) {
      document.body.classList.toggle("nav-open", open);
      navToggle.setAttribute("aria-expanded", open ? "true" : "false");
      navToggle.setAttribute("aria-label", open ? "Cerrar menú" : "Abrir menú");
    }
    navToggle.addEventListener("click", function () {
      setNav(!document.body.classList.contains("nav-open"));
    });
    navBackdrop.addEventListener("click", function () {
      setNav(false);
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && document.body.classList.contains("nav-open")) setNav(false);
    });
    var nav = document.getElementById("main-nav");
    if (nav) {
      nav.addEventListener("click", function (e) {
        if (e.target.closest("a")) setNav(false);
      });
    }
  }

  // ---- Cargar entradas anteriores (AJAX, sin recargar) ----
  function loadMore(link) {
    link.textContent = "Cargando…";
    getText(link.href)
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, "text/html");
        var container = qs(".blog-posts");
        var frag = doc.querySelector(".blog-posts");
        if (container && frag) {
          Array.prototype.forEach.call(frag.children, function (node) {
            container.appendChild(node);
          });
        }
        var next = doc.querySelector(".load-more a");
        var lm = qs(".load-more");
        if (lm) {
          if (next) {
            lm.innerHTML = "";
            var a = document.createElement("a");
            a.href = next.href;
            a.textContent = "Cargar entradas anteriores ↓";
            lm.appendChild(a);
          } else {
            lm.parentNode.removeChild(lm);
          }
        }
        X.hooks.run("swap");
      })
      .catch(function () {
        link.textContent = "No se pudo cargar. Intentá de nuevo.";
      });
  }

  // ---- Limpieza de cachés de descargas (tbr_*) ----
  function cleanupDownloadCache() {
    var PREFIX = "tbr_",
      MAX_AGE = 30 * 24 * 3600e3,
      MAX_BYTES = 2 * 1024 * 1024;
    try {
      var now = Date.now(),
        total = 0,
        changed = false;
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (!k || k.indexOf(PREFIX) !== 0) continue;
        var raw = localStorage.getItem(k);
        total += raw ? raw.length : 0;
        var rec = null;
        try {
          rec = JSON.parse(raw);
        } catch (err) {}
        if (rec && rec.t && now - rec.t > MAX_AGE) {
          localStorage.removeItem(k);
          changed = true;
        }
      }
      if (!changed && total > MAX_BYTES) localStorage.clear();
    } catch (err) {}
  }

  // ---- Tema claro/oscuro (oscuro por defecto, persistido en localStorage, sin auto) ----
  var THEME_KEY = "xogalaxy.theme";
  function currentTheme() {
    try {
      return localStorage.getItem(THEME_KEY) || "dark";
    } catch (err) {
      return "dark";
    }
  }
  function applyTheme(theme) {
    document.documentElement.setAttribute("data-theme", theme);
    try {
      localStorage.setItem(THEME_KEY, theme);
    } catch (err) {}
    var btn = qs("#theme-toggle");
    if (!btn) return;
    var dark = theme === "dark";
    btn.setAttribute("aria-label", dark ? "Cambiar a modo claro" : "Cambiar a modo oscuro");
    var icon = btn.querySelector("[data-lucide]");
    if (icon) icon.setAttribute("data-lucide", dark ? "sun" : "moon");
    initIcons();
  }
  function setupTheme() {
    applyTheme(currentTheme());
    var btn = qs("#theme-toggle");
    if (btn) {
      btn.addEventListener("click", function () {
        applyTheme(document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark");
      });
    }
  }

  // ---- Compartir en redes (botones .share-btn dentro de .share-row) ----
  var SHARE_TARGETS = {
    facebook: function (i) { return "https://www.facebook.com/sharer/sharer.php?u=" + enc(i.url); },
    x: function (i) { return "https://twitter.com/intent/tweet?url=" + enc(i.url) + "&text=" + enc(i.title); },
    whatsapp: function (i) { return "https://api.whatsapp.com/send?text=" + enc(i.title) + "%20" + enc(i.url); },
    telegram: function (i) { return "https://t.me/share/url?url=" + enc(i.url) + "&text=" + enc(i.title); },
    linkedin: function (i) { return "https://www.linkedin.com/sharing/share-offsite/?url=" + enc(i.url); },
  };
  function enc(s) {
    return encodeURIComponent(s == null ? "" : String(s));
  }
  function shareInfo(row) {
    var c = qs('link[rel="canonical"]');
    var url =
      (row && row.getAttribute("data-share-url")) ||
      location.href ||
      (c && c.getAttribute("href")) ||
      "";
    var title = (row && row.getAttribute("data-share-title")) || document.title;
    return { url: url, title: title };
  }
  function sharePopup(url) {
    var w = Math.min(600, (global.screen && screen.width) || 600) - 40;
    var h = Math.min(520, (global.screen && screen.height) || 520) - 60;
    global.open(url, "_blank", "width=" + w + ",height=" + h + ",noopener,noreferrer");
  }
  function fallbackCopy(text) {
    var ta = el("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand("copy");
    } catch (err) {}
    document.body.removeChild(ta);
  }
  function copyFeedback(btn) {
    var svg = btn.querySelector("svg");
    var prev = svg ? svg.innerHTML : "";
    var label = btn.getAttribute("aria-label");
    if (svg) svg.innerHTML = '<path d="M20 6 9 17l-5-5"/>';
    btn.setAttribute("aria-label", "Enlace copiado");
    global.setTimeout(function () {
      if (svg) svg.innerHTML = prev;
      if (label) btn.setAttribute("aria-label", label);
    }, 1600);
  }
  function initShare() {
    if (!qsa(".share-row").length) return;
    document.addEventListener("click", function (e) {
      var btn = e.target && e.target.closest ? e.target.closest(".share-btn") : null;
      if (!btn) return;
      var row = btn.closest(".share-row");
      var info = shareInfo(row);
      var net = btn.getAttribute("data-share");
      if (net === "copy") {
        var done = function () {
          copyFeedback(btn);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(info.url).then(done, done);
        } else {
          fallbackCopy(info.url);
          done();
        }
        return;
      }
      if (net === "native") {
        if (navigator.share) {
          navigator
            .share({ title: info.title, url: info.url })
            .catch(function () {});
        } else {
          var done2 = function () {
            copyFeedback(btn);
          };
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(info.url).then(done2, done2);
          } else {
            fallbackCopy(info.url);
            done2();
          }
        }
        return;
      }
      var target = SHARE_TARGETS[net];
      if (target) sharePopup(target(info));
    });
  }

  X.core = {
    hooks: { add: addHook, run: runHooks },
    utils: { qs: qs, qsa: qsa, el: el, escHtml: escHtml, fmt: fmt, animateStat: animateStat, getJSON: getJSON, postJSON: postJSON, getText: getText },
    initIcons: initIcons,
    decorateTitle: decorateTitle,
    initFeedButton: initFeedButton,
    initShare: initShare,
    setupNav: setupNav,
    loadMore: loadMore,
    cleanupDownloadCache: cleanupDownloadCache,
    setupTheme: setupTheme,
  };
  X.hooks = { add: addHook, run: runHooks };
})(window);

/**
 * XO Galaxy — API client del backend propio.
 * URL base configurable: window.XOGALAXY_CONFIG.backend o la del worker.
 */
(function (global) {
  "use strict";

  var X = (global.XOGalaxy = global.XOGalaxy || {});
  var config = global.XOGALAXY_CONFIG || {};
  var BACKEND = config.backend || "https://backend.xogalaxy.workers.dev";

  function parse(res) {
    return res.json().catch(function () {
      return {};
    });
  }

  function apiError(res, data) {
    var err = new Error((data && data.error) || "HTTP " + res.status);
    err.status = res.status;
    return err;
  }

  function get(url, headers) {
    return fetch(BACKEND + url, { headers: Object.assign({ accept: "application/json" }, headers || {}) }).then(function (r) {
      return parse(r).then(function (d) {
        if (!r.ok) throw apiError(r, d);
        return d;
      });
    });
  }

  function post(url, body, headers) {
    return fetch(BACKEND + url, {
      method: "POST",
      headers: Object.assign({ "Content-Type": "application/json", accept: "application/json" }, headers || {}),
      body: JSON.stringify(body || {}),
    }).then(function (r) {
      return parse(r).then(function (d) {
        if (!r.ok) throw apiError(r, d);
        return d;
      });
    });
  }

  function followers() {
    return get("/followers");
  }

  function visits(hit) {
    return get("/visits" + (hit ? "?hit=1" : ""));
  }

  function chatHistory(room, limit) {
    var url = "/chat/history?room=" + encodeURIComponent(room || "general");
    if (limit) url += "&limit=" + limit;
    return get(url);
  }

  function chatSend(room, nickname, body, token) {
    return post("/chat/message", { room: room, nickname: nickname, body: body, token: token || null });
  }

  // ---- autenticación (Google ID token) ----
  function authVerify(token) {
    return post("/auth/verify", { token: token }).then(function (d) {
      return { sub: d.sub, name: d.name, picture: d.picture, isOwner: !!d.isOwner };
    });
  }
  function authConfig() {
    return get("/auth/config");
  }

  // ---- comentarios ----
  function commentsList(postId) {
    return get("/comments?postId=" + encodeURIComponent(postId));
  }
  function commentsCount(postId) {
    return get("/comments?postId=" + encodeURIComponent(postId) + "&count=1");
  }
  function commentsCounts(ids) {
    return get("/comments/counts?ids=" + encodeURIComponent(ids.join(",")));
  }
  function commentsTotal() {
    return get("/comments/total");
  }
  function commentsCreate(data) {
    return post("/comments", data);
  }
  function commentsModPending(token) {
    return get("/comments/mod/pending", { "X-XOGALAXY-Token": token });
  }
  function commentsModReview(id, action, token) {
    return post("/comments/mod/review", { id: id, action: action }, { "X-XOGALAXY-Token": token });
  }
  function commentsDelete(id, token) {
    return post("/comments/delete", { id: id, token: token || null });
  }

  X.api = {
