/**
 * XO Galaxy — router SPA (History API).
 * Navegación suave entre páginas del blog: fetch + swap de <main.main-layout>,
 * pushState/popstate, delegación de clics y hooks 'swap' tras cada intercambio.
 */
(function (global) {
  "use strict";

  var X = (global.XOGalaxy = global.XOGalaxy || {});
  var core = X.core;
  var MAIN_SELECTOR = "main.main-layout";

  function afterSwap() {
    core.initIcons();
    X.hooks.run("swap");
  }

  function navigate(url, replace) {
    return core.utils
      .getText(url)
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, "text/html");
        var next = doc.querySelector(MAIN_SELECTOR);
        var current = document.querySelector(MAIN_SELECTOR);
        if (!next || !current) {
          location.href = url;
          return;
        }
        current.innerHTML = next.innerHTML;
        var t = doc.querySelector("title");
        if (t) document.title = t.textContent;

        var state = { url: url };
        if (replace) history.replaceState(state, "", url);
        else history.pushState(state, "", url);

        var hashIndex = url.indexOf("#");
        if (hashIndex >= 0) {
          var hash = url.slice(hashIndex);
          var target = document.querySelector(hash);
          if (target) target.scrollIntoView();
          else window.scrollTo(0, 0);
        } else {
          var postTitle = document.querySelector(".post-single .post-title");
          if (postTitle) postTitle.scrollIntoView({ block: "start" });
          else window.scrollTo(0, 0);
        }
        afterSwap();
      })
      .catch(function () {
        location.href = url;
      });
  }

  function onClick(e) {
    var lm = e.target.closest ? e.target.closest(".load-more a") : null;
    if (lm) {
      e.preventDefault();
      core.loadMore(lm);
      return;
    }
    var link = e.target.closest ? e.target.closest("a") : null;
    if (!link || e.defaultPrevented) return;
    if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    var t = link.target;
    if (t && t !== "_self") return;
    var href = link.getAttribute("href");
    if (!href) return;
    if (href.charAt(0) === "#") return;
    if (link.closest(".hero-actions")) return;
    var url;
    try {
      url = new URL(href, location.href);
    } catch (err) {
      return;
    }
    if (url.origin !== location.origin) return;
    var samePath = url.pathname + url.search === location.pathname + location.search;
    if (samePath) return;
    e.preventDefault();
    X.router.navigate(url.pathname + url.search + url.hash);
  }

  function init() {
    window.addEventListener("popstate", function () {
      navigate(location.href, true);
    });
    document.addEventListener("click", onClick);
  }

  X.router = { init: init, navigate: navigate, afterSwap: afterSwap };
})(window);

/**
 * XO Galaxy — chunk auth.
 * Login con Google Identity Services (GIS). El client id se resuelve de forma
 * perezosa: primero window.XOGALAXY_CONFIG.googleClientId, luego el cache de
 * sessionStorage y por último GET /auth/config del backend (sin secretos).
 * El ID token se guarda solo en memoria (nada de localStorage); el perfil
 * verificado llega del backend (/auth/verify). Se corre X.hooks.run("auth")
 * tras login/logout para que comentarios y chat refresquen su identidad.
 */
(function (global) {
  "use strict";

  var X = (global.XOGalaxy = global.XOGalaxy || {});
  var STORAGE_KEY = "xogalaxy_client_id";

  var CLIENT_ID = "";
  var token = null;
  var profile = null;
  var initialized = false;
  var loading = false;
  var pendingButtons = [];
  var listeners = [];
  var ensuring = null;

  function emit() {
    X.hooks.run("auth");
    listeners.forEach(function (fn) {
      try {
        fn(profile);
      } catch (err) {}
    });
  }

  function setProfile(p) {
    profile = p || null;
    emit();
  }

  function handleCredential(res) {
    if (!res || !res.credential) return;
    token = res.credential;
    X.api
      .authVerify(token)
      .then(function (p) {
        setProfile(p);
      })
      .catch(function () {
        token = null;
        setProfile(null);
      });
  }

  function readConfigId() {
    var c = global.XOGALAXY_CONFIG || {};
    return c.googleClientId || "";
  }

  function readCachedId() {
    try {
      return global.sessionStorage.getItem(STORAGE_KEY) || "";
    } catch (err) {
      return "";
    }
  }

  function cacheId(id) {
    try {
      if (id) global.sessionStorage.setItem(STORAGE_KEY, id);
      else global.sessionStorage.removeItem(STORAGE_KEY);
    } catch (err) {}
  }

  function ensureClientId() {
    if (CLIENT_ID) return Promise.resolve(CLIENT_ID);
    if (ensuring) return ensuring;
    var fromConfig = readConfigId();
    if (fromConfig) {
      CLIENT_ID = fromConfig;
      return Promise.resolve(CLIENT_ID);
    }
    var fromCache = readCachedId();
    if (fromCache) {
      CLIENT_ID = fromCache;
      return Promise.resolve(CLIENT_ID);
    }
    ensuring = X.api
      .authConfig()
      .then(function (d) {
        CLIENT_ID = (d && d.clientId) || "";
        cacheId(CLIENT_ID);
        return CLIENT_ID;
      })
      .catch(function () {
        CLIENT_ID = "";
        return "";
      })
      .finally(function () {
        ensuring = null;
      });
    return ensuring;
  }

  function initGoogle() {
    if (!global.google || !global.google.accounts || !CLIENT_ID) return;
    initialized = true;
    global.google.accounts.id.initialize({
      client_id: CLIENT_ID,
      callback: handleCredential,
      auto_select: false,
      cancel_on_tap_outside: true,
    });
    var btns = pendingButtons;
    pendingButtons = [];
    btns.forEach(function (el) {
      renderGoogleButton(el);
    });
  }

  function loadScript() {
    if (loading || initialized || !CLIENT_ID) return;
    loading = true;
    var s = document.createElement("script");
    s.src = "https://accounts.google.com/gsi/client";
    s.async = true;
    s.defer = true;
    s.onload = function () {
      loading = false;
      initGoogle();
    };
    s.onerror = function () {
      loading = false;
    };
    try {
      document.head.appendChild(s);
    } catch (err) {
      loading = false;
    }
  }

  function ensureReady() {
    return ensureClientId().then(function (id) {
      if (id) loadScript();
    });
  }

  function renderGoogleButton(el) {
    if (!el) return;
    try {
      global.google.accounts.id.renderButton(el, {
        theme: "outline",
        size: "medium",
        text: "continue_with",
        shape: "pill",
      });
    } catch (err) {}
  }

  function renderButton(el) {
    if (!el) return;
    if (initialized && CLIENT_ID) {
      renderGoogleButton(el);
      return;
    }
    pendingButtons.push(el);
    if (CLIENT_ID) loadScript();
    else ensureReady();
  }

  function login() {
    ensureReady().then(function () {
      if (!initialized) return;
      try {
        global.google.accounts.id.prompt(handleCredential);
      } catch (err) {}
    });
  }

  function logout() {
    token = null;
    setProfile(null);
    if (initialized) {
      try {
        global.google.accounts.id.disableAutoSelect();
      } catch (err) {}
    }
  }

  function init() {
    ensureReady();
  }

  function onAuthChange(fn) {
    listeners.push(fn);
    return function () {
      var i = listeners.indexOf(fn);
      if (i >= 0) listeners.splice(i, 1);
    };
  }

  X.auth = {
    init: init,
    login: login,
    logout: logout,
    renderButton: renderButton,
    onAuthChange: onAuthChange,
    getProfile: function () {
      return profile;
    },
    getToken: function () {
      return token;
    },
    isOwner: function () {
      return !!(profile && profile.isOwner);
    },
    _setProfile: setProfile,
    _setToken: function (t) {
      token = t || null;
    },
    _handleCredential: handleCredential,
    _setClientId: function (id) {
      CLIENT_ID = id || "";
      ensuring = null;
      cacheId(CLIENT_ID);
    },
  };
})(window);

/**
 * XO Galaxy — chunk stats.
 * Contadores propios: posts (feed público Blogger), seguidores y visitas (backend propio).
 * init() se llama en la carga real (visitas = HIT); refresh() tras cada navegación SPA (GET, no infla).
 */
(function (global) {
  "use strict";

  var X = (global.XOGalaxy = global.XOGalaxy || {});
  var utils = X.core.utils;
  var api = X.api;

  function loadPosts() {
    fetch("/feeds/posts/summary?alt=json&max-results=0")
      .then(function (r) {
        return r.json();
      })
      .then(function (data) {
        var total = parseInt(data.feed && data.feed.openSearch$totalResults && data.feed.openSearch$totalResults.$t, 10);
        utils.animateStat(utils.qs("#stat-posts"), total);
      })
      .catch(function () {
        var el = utils.qs("#stat-posts");
        if (el) el.textContent = "—";
      });
  }

  function loadComments() {
    api.comments
      .total()
      .then(function (d) {
        utils.animateStat(utils.qs("#stat-comments"), parseInt(d.total, 10));
      })
      .catch(function () {
        var el = utils.qs("#stat-comments");
        if (el) el.textContent = "—";
      });
  }

  function loadFollowers() {
    api
      .followers()
      .then(function (d) {
        utils.animateStat(utils.qs("#stat-followers"), parseInt(d.count, 10));
      })
      .catch(function () {
        var el = utils.qs("#stat-followers");
        if (el) el.textContent = "—";
      });
  }

  function loadVisits(hit) {
    api
      .visits(hit)
      .then(function (d) {
        utils.animateStat(utils.qs("#stat-visits"), parseInt(d.value, 10));
      })
      .catch(function () {});
  }

  function refresh() {
    loadPosts();
    loadComments();
    loadFollowers();
    loadVisits(false);
  }

  function init() {
    loadPosts();
    loadComments();
    loadFollowers();
    loadVisits(true);
  }

  X.hooks.add("swap", refresh);
  X.stats = { init: init, refresh: refresh };
})(window);

/**
 * XO Galaxy — chunk chat.
 * Chat propio sobre el backend (Durable Object Room, WS Hibernation).
 * Se monta en #chat-app (con data-room opcional). Si no existe, no hace nada.
 * Modo offline: si el WS no conecta, historia y envío caen a REST.
 */
(function (global) {
  "use strict";

  var X = (global.XOGalaxy = global.XOGalaxy || {});
  var utils = X.core.utils;
  var api = X.api;

  var BACKEND = X.config.backend;
  var WS_BASE = BACKEND.replace(/^https:/, "wss:").replace(/^http:/, "ws:");
  var NICK_KEY = "xogalaxy.nick";
  var LAST_READ_KEY = "xogalaxy.chat.lastRead";
  var MAX_MSGS = 200;
  var MAX_RETRY = 15000;
  var ONLINE_CLASS = "chat-online";
  var OFFLINE_CLASS = "chat-offline";
  var BADGE_SELECTOR = '.nav-link[href="#chat"] [data-chat-badge]';

  function create() {
    var app = utils.qs("#chat-app");
    if (!app) return null;

    var room = (app.getAttribute("data-room") || "general").slice(0, 64);
    var defaultNick = app.getAttribute("data-nick") || "Anónimo";
    var nickname = null;
    var customNick = null;
    function currentProfileName() {
      var p = X.auth.getProfile();
      return (p && p.name && p.name.trim()) || null;
    }
    try {
      customNick = localStorage.getItem(NICK_KEY);
      nickname = customNick || currentProfileName() || defaultNick;
    } catch (err) {
      nickname = currentProfileName() || defaultNick;
    }

    var root = utils.el("div", "xogalaxy-chat");
    var status = utils.el("p", "chat-status", "conectando…");
    var list = utils.el("ol", "chat-msgs");
    var form = utils.el("form", "chat-form");
    var nickInput = utils.el("input", "chat-nick");
    nickInput.maxLength = 32;
    nickInput.placeholder = "Nick";
    nickInput.value = nickname;
    nickInput.setAttribute("aria-label", "Tu apodo");
    var textInput = utils.el("input", "chat-input");
    textInput.maxLength = 1000;
    textInput.placeholder = "Escribí un mensaje…";
    textInput.autocomplete = "off";
    textInput.setAttribute("aria-label", "Mensaje");
    var sendBtn = utils.el("button", "chat-send", "Enviar");
    sendBtn.type = "submit";
    form.appendChild(nickInput);
    form.appendChild(textInput);
    form.appendChild(sendBtn);
    root.appendChild(status);
    root.appendChild(list);
    root.appendChild(form);
    app.appendChild(root);

    var ws = null;
    var retries = 0;
    var closed = false;
    var online = false;
    var unread = 0;
    var visible = false;
    var lastRead = readLastRead();

    function saveLastRead(ts) {
      lastRead = ts;
      try {
        localStorage.setItem(LAST_READ_KEY, String(ts));
      } catch (err) {}
    }

    function readLastRead() {
      try {
        var raw = localStorage.getItem(LAST_READ_KEY);
        if (raw === null) return null;
        var n = parseInt(raw, 10);
        return isNaN(n) ? null : n;
      } catch (err) {
        return null;
      }
    }

    function renderBadge() {
      var badge = utils.qs(BADGE_SELECTOR);
      if (!badge) return;
      if (unread > 0) {
        badge.textContent = unread > 99 ? "99+" : String(unread);
        badge.removeAttribute("hidden");
      } else {
        badge.setAttribute("hidden", "");
      }
    }

    function clearUnread() {
      if (unread === 0) return;
      unread = 0;
      renderBadge();
    }

    function onIncoming(message) {
      if (visible) {
        saveLastRead(message.createdAt);
        clearUnread();
        return;
      }
      unread += 1;
      renderBadge();
    }

    function setVisible(v) {
      visible = !!v;
      if (visible) {
        saveLastRead(Date.now());
        clearUnread();
      }
    }

    function isInViewport() {
      var rect = app.getBoundingClientRect();
      if (!rect || (rect.width === 0 && rect.height === 0)) return false;
      return (
        rect.top < (global.innerHeight || 0) &&
        rect.bottom > 0 &&
        rect.left < (global.innerWidth || 0) &&
        rect.right > 0
