      observer.observe(app);
    } else {
      global.addEventListener("scroll", onViewportChange);
      global.addEventListener("resize", onViewportChange);
      onViewportChange();
    }

    connect();
    return {
      root: root,
      setVisible: setVisible,
      close: function () {
        closed = true;
        if (unbindAuth) {
          unbindAuth();
          unbindAuth = null;
        }
        if (ws) {
          try {
            ws.close();
          } catch (err) {}
        }
        document.removeEventListener("click", onDocClick);
        if (observer) {
          try {
            observer.disconnect();
          } catch (err) {}
        }
        if (useFallback) {
          global.removeEventListener("scroll", onViewportChange);
          global.removeEventListener("resize", onViewportChange);
        }
      },
    };
  }

  var instance = null;
  function init() {
    if (instance || !utils.qs("#chat-app")) return;
    instance = create();
  }

  function reset() {
    if (instance) {
      instance.close();
      instance = null;
    }
  }

  function setVisible(visible) {
    if (instance) instance.setVisible(visible);
  }

  X.chat = { init: init, reset: reset, setVisible: setVisible };
})(window);

/**
 * XO Galaxy — chunk comentarios.
 * Comentarios propios del backend (D1). Montado en #comments-app dentro de
 * section#comments[data-post-id]. Lazy: primero solo el contador; la lista y
